head.script:
scwin.onpageload = function() {
    // 버튼 초기화
    btn_save.show("");
    btn_edit.hide();
    btn_delete.hide();

    // 페이지 정보 초기화
    scwin.initPaginationInfo();

    // 전체 데이터 조회를 위해 페이지 크기를 크게 설정
    dmp_testVo.set("pageIndex", "1");
    dmp_testVo.set("pageSize", "1000");

    //search_box
    var cptIbxName = $p.getComponentById("searchComp_1");
    if(cptIbxName == undefined){
        search_box.hide();
    }

    // 테스트관리 조회
    scwin.btn_search_onclick();
};

// 각 그리드별 페이지 정보 초기화
scwin.initPaginationInfo = function () {
    console.log("페이지 정보 초기화 시작");

    // 전체 데이터 페이지 정보
    scwin.allDataPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 대기 데이터 페이지 정보
    scwin.pendingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 진행중 데이터 페이지 정보
    scwin.runningPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 완료 데이터 페이지 정보
    scwin.completedPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };
};

// 페이지별 데이터 분할 함수
scwin.getPageData = function (data, pageInfo) {
    if (!data || !pageInfo) {
        console.error("getPageData: 데이터 또는 페이지 정보가 없습니다.");
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;
    return data.slice(startIndex, endIndex);
};

// 페이지 네비게이터 업데이트 함수
scwin.updatePagination = function (pageInfo, paginationComponent) {
    if (!pageInfo || !paginationComponent) {
        console.error("updatePagination: 페이지 정보 또는 컴포넌트가 없습니다.");
        return;
    }

    var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
    if (totalPages > 0) {
        paginationComponent.setCount(totalPages);
        paginationComponent.setSelectedIndex(pageInfo.currentPage);
    }
};

/************************** 이벤트 함수 *************************/

/**
 * 조회 버튼 클릭 이벤트
 */		   
scwin.btn_search_onclick = function(e) {
    if (!scwin.allDataPageInfo) {
        scwin.initPaginationInfo();
    }

    // 페이지번호 초기화
    dmp_testVo.set("pageIndex","1");
    dmp_testVo.set("pageSize","1000");
    scwin.allDataPageInfo.currentPage = 1;

    // 서버통신 - 테스트관리 조회
    $c.sbm.execute($p, sbm_selectTestVoList);
};

scwin.sbm_testList_submitdone = function(e) {
    console.log("서버 응답 수신", e);

    if (!scwin.allDataPageInfo) {
        scwin.initPaginationInfo();
    }

    // error 수신시
    var elData = e.responseJSON.elData;
    var elHeader  = e.responseJSON.elHeader;
    if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 전체 데이터 저장
    var allData = elData.testVoList || [];
    console.log("전체 데이터:", allData.length, "개");

    scwin.allDataPageInfo.data = allData;
    scwin.allDataPageInfo.totalCount = elData.totalCount;

    // testResult별로 데이터 필터링
    var pendingData = [];
    var runningData = [];
    var completedData = [];

    for (var i = 0; i < allData.length; i++) {
        var item = allData[i];
        if (item.testResult === "PEN") {
            pendingData.push(item);
        } else if (item.testResult === "RUN") {
            runningData.push(item);
        } else if (item.testResult === "SUC" || item.testResult === "FAI") {
            completedData.push(item);
        }
    }

    // 각 그리드별 데이터 저장
    scwin.pendingPageInfo.data = pendingData;
    scwin.pendingPageInfo.totalCount = pendingData.length;
    scwin.pendingPageInfo.currentPage = 1;

    scwin.runningPageInfo.data = runningData;
    scwin.runningPageInfo.totalCount = runningData.length;
    scwin.runningPageInfo.currentPage = 1;

    scwin.completedPageInfo.data = completedData;
    scwin.completedPageInfo.totalCount = completedData.length;
    scwin.completedPageInfo.currentPage = 1;

    // 그리드 업데이트
    scwin.updateGridData();

    // 총 레코드 수 업데이트
    spn_listCnt.setLabel(elData.totalCount);
    spn_pendingListCnt.setLabel(pendingData.length);
    spn_runningListCnt.setLabel(runningData.length);
    spn_completedListCnt.setLabel(completedData.length);

    // 페이지 네비게이터 업데이트
    var serverPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: elData.totalCount
    };
    scwin.updatePagination(serverPageInfo, pgl_testList);
    scwin.updatePagination(scwin.pendingPageInfo, pgl_pending);
    scwin.updatePagination(scwin.runningPageInfo, pgl_running);
    scwin.updatePagination(scwin.completedPageInfo, pgl_completed);

    // 페이징 정보 업데이트
    var totalPageCount = Math.ceil(elData.totalCount / 10);
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_testVo.get("pageIndex"));

    // 폼 초기화
    dmp_testVoDetail.setEmptyValue();
};	

// 각 그리드 데이터 업데이트
scwin.updateGridData = function () {
    console.log("그리드 데이터 업데이트 시작");

    try {
        // 전체 데이터 그리드
        if (scwin.allDataPageInfo && scwin.allDataPageInfo.data) {
            var displayPageSize = 10;
            var currentPage = 1;
            var startIndex = 0;
            var endIndex = displayPageSize;

            var allPageData = scwin.allDataPageInfo.data.slice(startIndex, endIndex);
            dlt_testVoList.setJSON(allPageData);
        }

        // 대기 그리드
        if (scwin.pendingPageInfo && scwin.pendingPageInfo.data) {
            var pendingPageData = scwin.getPageData(scwin.pendingPageInfo.data, scwin.pendingPageInfo);
            dlt_pendingList.setJSON(pendingPageData);
        }

        // 진행중 그리드
        if (scwin.runningPageInfo && scwin.runningPageInfo.data) {
            var runningPageData = scwin.getPageData(scwin.runningPageInfo.data, scwin.runningPageInfo);
            dlt_runningList.setJSON(runningPageData);
        }

        // 완료 그리드
        if (scwin.completedPageInfo && scwin.completedPageInfo.data) {
            var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
            dlt_completedList.setJSON(completedPageData);
        }
    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
    }
};

/**
 * 페이지 번호 클릭 이벤트
 */
scwin.pgl_testList_onclick = function(idx) {
    // 페이지 번호 세팅
    dmp_testVo.set("pageIndex", idx);
    dmp_testVo.set("pageSize", "10");

    // 서버통신 - 테스트관리 조회
    $c.sbm.execute($p, sbm_selectTestVoList);
};

// 대기 데이터 페이지 클릭
scwin.pgl_pending_onclick = function (idx) {
    if (!scwin.pendingPageInfo) return;

    scwin.pendingPageInfo.currentPage = idx;
    var pendingPageData = scwin.getPageData(scwin.pendingPageInfo.data, scwin.pendingPageInfo);
    dlt_pendingList.setJSON(pendingPageData);
    pgl_pending.setSelectedIndex(idx);
};

// 진행중 데이터 페이지 클릭
scwin.pgl_running_onclick = function (idx) {
    if (!scwin.runningPageInfo) return;

    scwin.runningPageInfo.currentPage = idx;
    var runningPageData = scwin.getPageData(scwin.runningPageInfo.data, scwin.runningPageInfo);
    dlt_runningList.setJSON(runningPageData);
    pgl_running.setSelectedIndex(idx);
};

// 완료 데이터 페이지 클릭
scwin.pgl_completed_onclick = function (idx) {
    if (!scwin.completedPageInfo) return;

    scwin.completedPageInfo.currentPage = idx;
    var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
    dlt_completedList.setJSON(completedPageData);
    pgl_completed.setSelectedIndex(idx);
};

/**
 * 등록 버튼 클릭 이벤트
 */
scwin.btn_register_onclick = function(e) {
    // 테스트관리 dataMap 초기화
    dmp_testVoDetail.setEmptyValue();

    // 기본값 설정
    dmp_testVoDetail.set("testResult", "PEN"); // 기본값: 대기
    dmp_testVoDetail.set("isDeleted", "N"); // 기본값: 삭제되지 않음

    // 시연용 데이터 설정
    dmp_testVoDetail.set("taskId", "1");
    dmp_testVoDetail.set("taskName", "ERP 시스템 고도화 프로젝트");

    // 파일 목록 초기화
    dlt_upload.setJSON([]);
    dlt_attVoList.setJSON([]);

    // 등록 모드로 설정
    scwin.setFormMode("new");

    // 팝업 표시
    pop_overlay.show();

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("테스트 등록");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("테스트 등록");
            }, 50);
        }
    }, 50);

    // 미리보기 초기화
    scwin.hideAllPreviewPanels();
    scwin.showNoPreview();
};

/**
 * 그리드 셀 클릭 이벤트
 */
scwin.grd_list_oncellclick = function(row,col,colId) {
    dmp_testVoDetail.setJSON(dlt_testVoList.getRowJSON(row));

    // 수정 모드로 설정
    btn_save.hide(); 		// 저장 버튼 숨김
    btn_edit.show("");      // 수정 버튼 표시
    btn_delete.show("");    // 삭제 버튼 표시
};

/**
 * 그리드 셀 더블클릭 이벤트 - 상세보기/수정 팝업
 */
scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    // 선택된 행의 데이터를 상세 정보에 설정
    dmp_testVoDetail.setJSON(dlt_testVoList.getRowJSON(rowIndex));

    // 팝업 표시
    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("테스트 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("테스트 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

// 대기 그리드 더블클릭
scwin.pending_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_pendingList.getRowJSON(rowIndex);
    dmp_testVoDetail.setJSON(selectedData);

    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("대기 테스트 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("대기 테스트 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

// 진행중 그리드 더블클릭
scwin.running_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_runningList.getRowJSON(rowIndex);
    dmp_testVoDetail.setJSON(selectedData);

    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("진행중 테스트 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("진행중 테스트 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

// 완료 그리드 더블클릭
scwin.completed_grd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var selectedData = dlt_completedList.getRowJSON(rowIndex);
    dmp_testVoDetail.setJSON(selectedData);

    pop_overlay.show();

    // 조회 모드로 설정
    scwin.setFormMode("view");

    setTimeout(function() {
        try {
            spn_popupTitle.setValue("완료 테스트 상세정보");
        } catch(e) {
            setTimeout(function() {
                spn_popupTitle.setValue("완료 테스트 상세정보");
            }, 50);
        }
    }, 50);

    scwin.loadFileList();
};

// 테스트관리 clear
scwin.btn_reset_onclick = function(e) {
    // 테스트관리 dataMap 초기화
    dmp_testVoDetail.setEmptyValue();

    // 기본값 설정
    dmp_testVoDetail.set("testResult", "PEN");
    dmp_testVoDetail.set("isDeleted", "N");

    // 등록 모드로 설정
    scwin.setFormMode("new");
};

// 폼 모드 설정 함수
scwin.setFormMode = function(mode) {
    console.log("폼 모드 전환:", mode);

    if (mode === "edit") {
        // 수정 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();

    } else if (mode === "view") {
        // 조회 모드
        scwin.setFieldsReadOnly(true);
        scwin.setEditorMode(false);
        scwin.showFileUploadSection(false);

        // 버튼 상태 변경
        btn_save.hide();
        btn_popup_edit.show();
        btn_popup_delete.show();
    } else if (mode === "new") {
        // 등록 모드
        scwin.setFieldsReadOnly(false);
        scwin.setEditorMode(true);
        scwin.showFileUploadSection(true);

        // 버튼 상태 변경
        btn_save.show();
        btn_popup_edit.hide();
        btn_popup_delete.hide();
    }
};

// 필드 읽기 전용 설정 함수
scwin.setFieldsReadOnly = function(readOnly) {
    try {
        // 편집 가능한 필드들
        var editableFields = [
            "inp_name",          // 테스트 케이스명
            "inp_category",      // 테스트 카테고리
            "inp_inputData",     // 테스트 입력 데이터
            "inp_expectedResult", // 예상 결과
            "inp_actualResult",  // 실제 결과
            "inp_assignee",      // 테스트 담당자
            "cal_executionDate", // 테스트 실행일
            "inp_duration",      // 테스트 소요시간
            "sel_testResult"     // 테스트 결과
        ];

        editableFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(readOnly);
            }
        });

        // 업무명은 항상 readOnly
        var alwaysReadOnlyFields = ["inp_taskName"];
        alwaysReadOnlyFields.forEach(function(fieldId) {
            var field = $p.getComponentById(fieldId);
            if (field && field.setReadOnly) {
                field.setReadOnly(true);
            }
        });

    } catch(e) {
        console.error("필드 읽기 전용 설정 오류:", e);
    }
};

/**
 * 저장 버튼 클릭 이벤트
 */	
scwin.btn_save_onclick = function(e) {
    // 유효성 체크
    var name = dmp_testVoDetail.get("name");
    if (!name || name.trim() === "") {
        $c.win.alert("테스트 케이스명을 입력해주세요.");
        return;
    }

    scwin.sendTestAndFiles();
};

// 테스트와 파일 전송
scwin.sendTestAndFiles = function () {
    console.log("sendTestAndFiles() 시작됨");

    var formData = new FormData();

    formData.append("taskId", dmp_testVoDetail.get("taskId"));
    formData.append("name", dmp_testVoDetail.get("name"));
    formData.append("category", dmp_testVoDetail.get("category"));
    formData.append("scenario", dmp_testVoDetail.get("scenario"));
    formData.append("inputData", dmp_testVoDetail.get("inputData"));
    formData.append("expectedResult", dmp_testVoDetail.get("expectedResult"));
    formData.append("actualResult", dmp_testVoDetail.get("actualResult"));
    formData.append("testResult", dmp_testVoDetail.get("testResult") || "PEN");
    formData.append("assignee", dmp_testVoDetail.get("assignee"));
    formData.append("executionDate", dmp_testVoDetail.get("executionDate"));
    formData.append("duration", dmp_testVoDetail.get("duration"));

    // 파일 추가
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        console.log("fileList", fileList);

        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var realFile = fileList[i].file;
                console.log('real', realFile);
                formData.append("files", realFile);
            }
        }
    }

    fetch("/InsWebApp/TEST001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { return res.json(); })
    .then(function(res) {
        $c.win.alert("등록되었습니다.");
        dlt_upload.removeAll();
        if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
            mpd_html5Type.removeAllFiles();
        }
        pop_overlay.hide();
        scwin.btn_search_onclick();
    })
    .catch(function(err) {
        console.error("전송 실패", err);
        $c.win.alert("트랜잭션 실패");
    });
};

/**
 * 테스트 등록 콜백
 */
scwin.sbm_insertTestVo_submitdone = function(e) {
    // error 수신시
    var elHeader  = e.responseJSON.elHeader;
    if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }else{
        // 등록되었습니다. msg 출력
        $c.win.alert("등록되었습니다.");
        // 팝업 닫기
        pop_overlay.hide();
    }

    // 재조회
    scwin.btn_search_onclick();
};

/**
 * 수정 버튼 클릭 이벤트
 */		
scwin.btn_edit_onclick = function(e) {
    var testId = dmp_testVoDetail.get("id");
    var testName = dmp_testVoDetail.get("name");

    if (!testId || testId.trim() === "") {
        $c.win.alert("테스트 ID가 없습니다.");
        return;
    }

    if (!testName || testName.trim() === "") {
        $c.win.alert("테스트 케이스명을 입력해주세요.");
        return;
    }

    // 수정 모드로 전환
    scwin.setFormMode("edit");

    var promise = $c.win.confirm("수정하시겠습니까?");
    promise.then(function (result) {
        if (result) {
            $c.sbm.execute($p, sbm_updateTestVo);
        } else {
            // 취소 시 조회 모드로 복귀
            scwin.setFormMode("view");
        }
    });
};

// 팝업 수정 버튼 클릭 이벤트
scwin.btn_popup_edit_onclick = function(e) {
    // 수정 모드로 전환
    scwin.setFormMode("edit");
};

/**
 * 테스트 수정 콜백
 */
scwin.sbm_updateTestVo_submitdone = function(e) {
    // error 수신시
    var elHeader  = e.responseJSON.elHeader;
    if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }else{
        // 수정되었습니다. msg 출력
        $c.win.alert("수정되었습니다.");

        // 조회 모드로 전환
        scwin.setFormMode("view");
    }
    // 재조회
    scwin.btn_search_onclick();
};

/**
 * 삭제 버튼 클릭 이벤트
 */		
scwin.btn_delete_onclick = function(e) {
    var testId = dmp_testVoDetail.get("id");

    if (!testId) {
